#!/bin/bash
# keys27 = keys24 (PEI scheduler path disabled) + keys25 (probe at END of APRIORI) + keys26 (FDT scan)
#
# Mistake being corrected: keys25/keys26 were generated by sed from build_keys23.sh, but the
# "disable scheduler/FV-list path" fix never lived in a build script - it was a temporary edit
# inside run_keys24.sh with a trap-restore.  So keys25/keys26 were compiled WITHOUT it and died
# in PEI with the old "Synchronous Exception at 0xA7102B98".
set -e
cd /mnt/d/本地项目-01/_k70port_extract/wsl

PP=/root/k70/uefi/Silicon/Qualcomm/QcomPkg/Library/PlatformPeiLib/PlatformPei.c
cp "$PP" /tmp/PlatformPei.c.bak27
trap 'cp /tmp/PlatformPei.c.bak27 "$PP"' EXIT

python3 - "$PP" <<'PY'
import sys, pathlib
p = pathlib.Path(sys.argv[1])
s = p.read_text(encoding="utf-8")
old = "  // Check Scheduler Address\n  if (SchedulerInterfaceAddr) {"
new = ("  // keys24/keys27: GetXblHobAddresses() hands back a GUID table entry, not EFI_KERNEL_PROTOCOL;\n"
       "  // calling SchedulerProtocol->Lock->InitLock() there faults (Synchronous Exception in PEI).\n"
       "  // Mu builds its own FV HOB, so skip the FV-list path and keep only the DT extension HOB.\n"
       "  if (0) {")
assert old in s, "scheduler block not found"
s = s.replace(old, new, 1)
p.write_text(s, encoding="utf-8")
print("patched PlatformPei.c: scheduler/FV-list path disabled")
PY

# build_keys25.sh = keys23 base + probe inserted after RscDxe (end of APRIORI)
bash build_keys25.sh keys27 2>&1 | tail -14

bash pack_keys.sh /mnt/d/本地项目-01/_k70port_extract/qemu-fw/SILICIUM_UEFI-keys27.fd keys27 2>&1 | tail -8
echo "===== ARTIFACTS ====="
ls -l /mnt/d/本地项目-01/K70-UEFI-build/Mu-vermeer-keys27*.img 2>/dev/null
sha256sum /mnt/d/本地项目-01/K70-UEFI-build/Mu-vermeer-keys27*.img 2>/dev/null
